# make scaling reflect squeeze more plausibly and cracks based on crack amount
s=s.replace("if(crashU)g.scale(1+crashU*.34,1-crashU*.46);","if(crashU)g.scale(1+crashU*.28,Math.max(.5,1-crashU*.42));",1)
s=s.replace("if(crashU>.12){g.strokeStyle='#698d96';g.lineWidth=Math.max(1,base*.025);g.globalAlpha=.45+.5*crashU;for(let k=0;k<6;k++){let a=-Math.PI*.82+k*.31+Math.sin(k*8.1)*.08,len=base*(.25+.28*crashU);", "if(crashCracks>.08){g.strokeStyle='#698d96';g.lineWidth=Math.max(1,base*.025);g.globalAlpha=.32+.62*crashCracks;for(let k=0;k<7;k++){let a=-Math.PI*.86+k*.285+Math.sin(k*8.1)*.08,len=base*(.18+.42*crashCracks);",1)
s=s.replace("let plume=state==='crash'?Math.max(0,Math.round((1-crashU)*Math.min(IS_MOBILE?14:22,4+base/6))):", "let plume=state==='crash'?Math.max(0,Math.round((1-Math.min(1,crashCracks))*Math.min(IS_MOBILE?14:22,4+base/6))):",1)
# marks render support crack type
oldmark="if(m.kind==='impact'){g.fillStyle=m.c;g.beginPath();g.ellipse(m.x,m.y,m.size*1.5,m.size*.65,0,0,TAU);g.fill()}else{px(m.x,m.y,m.size*1.5,m.size,m.c)}"
newmark="if(m.kind==='impact'){g.fillStyle=m.c;g.beginPath();g.ellipse(m.x,m.y,m.size*1.5,m.size*.65,0,0,TAU);g.fill()}else if(m.kind==='crack'){g.strokeStyle=m.c;g.lineWidth=Math.max(worldPixelSize(),1.5/camera.finalZoom);g.beginPath();g.moveTo(m.x,m.y);g.lineTo(m.x+Math.cos(m.angle||0)*m.size,m.y+Math.sin(m.angle||0)*m.size*.35);g.stroke()}else{px(m.x,m.y,m.size*1.5,m.size,m.c)}"
if oldmark not in s: raise SystemExit('mark pattern not found')
s=s.replace(oldmark,newmark,1)
# update assertion/info text
s=s.replace("console.assert(typeof handleEscaped==='function'&&typeof recoverLife==='function','survival life loop');", "console.assert(typeof handleEscaped==='function'&&typeof recoverLife==='function','survival life loop');console.assert(typeof beginDeathCrash==='function'&&typeof spawnDeathShards==='function','two-stage death crash');",1)
s=s.replace("natural snow growth, verified survival death path, polished HUD/UI", "natural snow growth, two-stage impact death, polished HUD/UI",1)
p.write_text(s,encoding='utf-8')
print('patched', len(s))
